from taf.hw.hp.redfish.provider import RedfishProvider


class RedfishConnection(object):
    def __init__(self, host, username, password, port='443', redfish_version='dl110g11_bmc', alias=None):
        """
        Connects to desired HP iLO interface.

        :param str address: HP iLO ip address ie. 10.19.141.2
        :param int port: Port number, Default is 443
        :param str username: iLO endpoint username
        :param str password: iLO endpoint password for username
        :param str redfish_version: (Optional) Version of iLO redfish interface
        :raises: Exceptions are documented in taf.hw.hp.redfish supported interfaces
        """
        self._redfish = RedfishProvider.create_redfish(host, username, password, port, redfish_version, alias)

    def get_system_info(self, check_status=None, query_parameters=''):
        """
        Get the system info.
        :param bool check_status: (Optional) check status flag. Support True or False.
                                  if not provided, global default value is True.
        :param str query_parameters: (Optional) query parameters, Please refer to redfish specification.
                          e.g. $expand, $filter, $select and so on.
        :return: system info dict.

        """
        return self._redfish.get_system_info(check_status, query_parameters=query_parameters)

