    def create_new_user_account(self, user_name, user_password, role_id="Administrator", check_status=None):
        """
        Create new user account.

        :param str user_name: (mandatory) user name, Please refer to redfish specification.
        :param str user_password: (mandatory) user password, Please refer to redfish specification.
        :param str role_id: (Optional) new password, Please refer to redfish specification.
                    Supported values: Administrator, Operator, ReadOnly or None.
        :param bool check_status: (Optional) check status flag. Support True or False.
                          if not provided, global default value is True.
        :return: response dict.
        """
        return self._redfish.create_new_user_account(user_name=user_name, user_password=user_password,
                                                     role_id=role_id, check_status=check_status)

    def delete_user_account(self, user_id, check_status=None):
        """
        Delete user account.

        :param str user_id: (mandatory) user id, Please refer to redfish specification.
        :param bool check_status: (Optional) check status flag. Support True or False.
                          if not provided, global default value is True.
        :return: response dict. For example:
                        {
                            "error": {
                                "code": "iLO.0.10.ExtendedInfo",
                                "message": "See @Message.ExtendedInfo for more information.",
                                "@Message.ExtendedInfo": [
                                    {
                                        "MessageId": "Base.1.18.AccountRemoved"
                                    }
                                ]
                            }
                        }
        """
        return self._redfish.delete_user_account(user_id=user_id, check_status=check_status)

