    def insert_virtual_media(self, http_server_ip, virtual_media_file_name, remote_file_share_num=2,
                             check_status=None):
        """
        Insert virtual media file.

        :param str virtual_media_file_name: (mandatory) virtual media file name,
                    for example: Air-TA-Live-x86_64.iso.
        :param str http_server_ip: (mandatory) http server ip address,
                                    for example 10.16.61.169
        :param int remote_file_share_num: (Optional) remote file share num. Support 1 or 2,
                    1 is supported media types are "Floppy" and "USBStick";
                    2 is supported media types are "DVD" and "CD";
                    the default value is 2.
        :param bool check_status: (Optional) check status flag. Support True or False.
                          if not provided, global default value is True.
        :return: Execution respose dict. For example:
                {
                    "error": {
                        "code": "iLO.0.10.ExtendedInfo",
                        "message": "See @Message.ExtendedInfo for more information.",
                        "@Message.ExtendedInfo": [
                            {
                                "MessageId": "Base.1.18.Success"
                            }
                        ]
                    }
                }
        """
        return self._redfish.insert_virtual_media(http_server_ip=http_server_ip,
                                                  virtual_media_file_name=virtual_media_file_name,
                                                  remote_file_share_num=remote_file_share_num,
                                                  check_status=check_status)

    def eject_virtual_media(self, remote_file_share_num=2, check_status=None):
        """
        Eject virtual media file.

        :param int remote_file_share_num: (Optional) remote file share num. Support 1 or 2,
                    1 is supported media types are "Floppy" and "USBStick";
                    2 is supported media types are "DVD" and "CD";
                    the default value is 2.
        :param bool check_status: (Optional) check status flag. Support True or False.
                          if not provided, global default value is True.
        :return: Execution respose dict. For example:
                {
                    "error": {
                        "code": "iLO.0.10.ExtendedInfo",
                        "message": "See @Message.ExtendedInfo for more information.",
                        "@Message.ExtendedInfo": [
                            {
                                "MessageId": "Base.1.18.Success"
                            }
                        ]
                    }
                }
        """
        return self._redfish.eject_virtual_media(remote_file_share_num=remote_file_share_num,
                                                  check_status=check_status)

    def set_bmc_attributes(self, service_name, new_attributes, check_status=True):
        """
        Set bmc attributes.

        .. note::
            **API used:** ``PATCH /redfish/v1/Managers/1/{service_name}``

            For details refer to `Manager resource definitions`_.

        .. _Manager resource definitions: https://servermanagementportal.ext.hpe.com/docs/redfishservices/ilos/ilo6/ilo6_170/ilo6_manager_resourcedefns170/

        :param str service_name: (mandatory) set attribute in given service,
                for example: ``DateTime``, ``NetworkProtocol``, ``SecurityService`` and so on.
        :param dict new_attributes: (mandatory) new attribute dict.
            For example::
                {"Oem":{"Hpe":{"RemoteSyslogEnabled":True,"RemoteSyslogPort":514,"RemoteSyslogServer":"10.0.0.0"}}}
        :param bool check_status: (Optional) Check response and raise HTTPError if one occurred.
        :return: Execution response dict.
            For example::

                {
                    "error": {
                        "code": "iLO.0.10.ExtendedInfo",
                        "message": "See @Message.ExtendedInfo for more information.",
                        "@Message.ExtendedInfo": [
                            {
                                "MessageId": "Base.1.18.Success"
                            }
                        ]
                    }
                }
        """
        return self._redfish.set_bmc_attributes(service_name=service_name, new_attributes=new_attributes,
                                                check_status=check_status)

    def disconnect(self):
        """
        Disconnect the current session from the HP iLO.
        :return: None
        """
        return self._redfish.disconnect()
